  VALUES 
    (315::BIGINT, 'La cabra de compu ???????????? Suele dejar laboratorios de 12 ejercicios cortos sobre el tema que vimos esa semana, lo que ayuda a que uno aprenda muy bien el tema. Los proyectos suelen ser juegos, lo cual esta muy bien, y en intro si califica 100% en 4 exámenes, no desaproveche llevar con él.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-10-19T00:00:00+00:00'::TIMESTAMPTZ, '9022b8c0fdfed8c020bb1cbc0bf9543aba08daf0bd2bda3aaf1e7f44e4ea0e7d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
