    (315::BIGINT, 'Increíble profesor, trabajos sencillos y proyectos muy accesibles. Magnifica persona, no duden en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '52b3d9999e355c4429c13eb17c955179e4667cba152b3709e15851f39d33380d'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'En profe hace las clases divertidas, se aprende y no es aburrido. Matricule sin miedo, no es estricto'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-19T00:00:00+00:00'::TIMESTAMPTZ, '345c9ea9406f6b726a8b8750441886df0a8dde4399961ce09fd2beed08d0effe'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Es como un osito de peluche, es todo buena nota y le importa muchísimo que la gente entienda bien. Es super comprensivo con todo y siempre busca la forma de ayudarlo a uno, sin lugar a duda, uno de los mejores profes que tiene el Tec.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, '14dda0f7179ec7a98d88061f6598aed7238ced621753bc2f9bca6d8dc3e31bb3'::TEXT, ARRAY[1249]::BIGINT[]),
    (315::BIGINT, 'Literal es y será la mejor opción para compu, el mejor profe de todos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '3a60abd46a467eedea5c87b75beb46ca217bfbd10e5c1f1b7995c9e95126a702'::TEXT, ARRAY[1249]::BIGINT[]),
    (315::BIGINT, 'Excelente profesor, es flexible con las fechas de entrega, le gusta hacer kahoots por puntos extra, y si está dentro de sus posibilidades, hace gira a Microsoft lo cual me parece destacable ya que la mayoría de profesores se preocupan por dar la materia que les corresponde y ya.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-28T00:00:00+00:00'::TIMESTAMPTZ, '16803a7c804b7f87d06f25db0b52c21049001a768de26d3b421b9dff155a02ef'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Uno de los mejores profes de la carrera, es muy amistoso con sus estudiantes y realmente le interesa la participación en clase. Se aprende bastante y el curso es muy llevadero y ligero, en parte por un buen método de enseñanza, matricule con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'a2aff8d02596b43d1d4bf7457d49dfc5e326946b8dde445c7625b2b988b3335e'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'db285b1c74d44b546a35843715344b0ed0f1071cb24364b7eb9fd80cf2ce4eb1'::TEXT, ARRAY[1249]::BIGINT[]),
    (315::BIGINT, 'Es un profe excelente y muy comprensivo. Se nota que le gusta enseñar y explica de forma muy clara, con él de verdad se aprende mucho. No dude en matricular con él este curso o alguno otro que imparta. Sus clases son entretenidas y siempre tiene la disposición de ayudar a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, '525b2b13d7499e3903e4396688b78fd2145c1730a9cf79755af49a1a24c2b00a'::TEXT, ARRAY[1249]::BIGINT[]),
    (315::BIGINT, 'Muy buen profe, ayuda bastante a los estudiantes. Lo único malo es que revisa los trabajos entregados hasta el final de semestre, entonces uno no sabe su nota hasta que se entreguen actas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'a82bffc2a34f2851aa49c3fac5af19eb92084e4992194403b6901596ebfaaeba'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Se preocupa porque los estudiantes comprendan y explica bien, da mucho apoyo y hace que el ambiente sea agradable. Son 4 proyectos pero se ven en clases los paradigmas que hay que usar en cada uno. No dude en matricular con él, además nos llevó de gira a Intel y a Microsoft :D'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '0ea64de1b83718c5fd72b0aa0025249005ee7e2a481a020362efa9e54bcf08b9'::TEXT, ARRAY[1045]::BIGINT[]),
    (315::BIGINT, 'Facil, asi FACIL el MEJOR profesor de todo el TEC, pero es que ni dude matricular con el, cuando le aparezca en algun curso sepalo que es una bendicion. Es super pura vida y hace lo posible para que los estudiantes entiendan y no sientan el curso como una carga, sino como un espacio para aprender.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'beb1c8f1f185f7405b105fa5499bb547f05de0bcc412311c0d2957f8b0958492'::TEXT, ARRAY[1045]::BIGINT[]),
    (315::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b449bd7c198c74e769e1407c1054422d73b2d0a724c9560de0b24cbc21e81549'::TEXT, ARRAY[1249]::BIGINT[]),
    (315::BIGINT, 'Buen profesor, explica y vuelve a explicar si es necesario para que todos entendamos el tema, si piden ayuda, la da, aunque a veces se tarda un poco en responder los mensajes, pero en general, recomiendo llevar la clase con él si pueden, inclusive otros cursos que no necesariamente sea elementos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3bf1d51eb6217dca1442bd0ccf02027f8237cfa7e47b836eaee2ecba3c20a7e7'::TEXT, ARRAY[1249]::BIGINT[]),
    (315::BIGINT, 'Uno de los mejores profes que hay en el TEC, matricularía con él cualquier curso fácilmente. Lo único es que a veces explica muy rápido pero por lo demás es excelente. Buen profesor, buena persona, se preocupa por los estudiantes. Hacen falta más docentes como él. Bryan GOAT.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e8165ba1a06428db5aea0aae7cee385fd7fd01d049cfe083877c8417d10876dd'::TEXT, ARRAY[1045]::BIGINT[]),
    (315::BIGINT, 'El mejor profe para llevar Lenguajes, sin duda da mucho apoye para que uno pase, ponerle a los proyectos y en lo demás con buena pareja o grupo sale fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-05-31T00:00:00+00:00'::TIMESTAMPTZ, '74f7b0fcccd7c456e527b8db6e75ac66a20c9cb0caf9e8ada70393a0cac562de'::TEXT, ARRAY[1045]::BIGINT[]),
    (315::BIGINT, 'Este profe es fácil el mejor con el que he llevado en toda la carrera, desde el ambiente tan agradable que pone en sus clases hasta el esfuerzo que hace por entender y hacer que sus estudiantes disfruten el curso. Lo mejor es que Brayan es el único profe que conozco que busca hacer giras.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-05-30T00:00:00+00:00'::TIMESTAMPTZ, '7c06fa6054e612096e84248e2492fbcb087b4c3efdf4a779d4a5d07080ab6c90'::TEXT, ARRAY[1045]::BIGINT[]),
    (315::BIGINT, 'El mejor profe del tec, tqm brayitan'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-30T00:00:00+00:00'::TIMESTAMPTZ, '65a280433d499e70ce2db46edc09f6b203f086be9df4d91d12d545c45e6d57e4'::TEXT, ARRAY[1045]::BIGINT[]),
    (315::BIGINT, 'Muy buen profe, pura vida y hace las clases entretenidas y da puntos extra durante actividades de clase. Lo único es que en ocasiones no responde las dudas por telegram.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, '47a4060c4f9d55cf6e8b3a44672b9f928e4a0105150ac57e4d0dce9cbbf95dd4'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Muy buen Profe, Pura Vida, la materia puede llegar a ser aburrida pero el trata que las clases sean entretenidas, crea un buen ambiente y busca la participación de los estudiantes. Le interesa que uno aprenda, da bueno retroalimentación. Deja muchos trabajos pero nada del otro mundo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '88185755b7cefac121177cec405489550d5515f811178f27b0dd9312426bd19b'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Es un muy buen profe, muy pura vida, las clases al ser virtuales a veces son un poco cansadas de ver pero todas las semanas hace kahoots y laboratorios que hacen que estas clases sean un poco más entretenidas. No es muy duro para calificar. Todas las semanas hay trabajos pero no muy duros.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'b608b697cd63207e3f341c987095fa5b017ab87dba27dc676d40d77c312ec24e'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3281b9e12f864d0c685b2a41e0582dc7c9fa2da80ba0fe0104b2013f4e348d97'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Muy buen profesor, explica muy bien, es muy amable con sus estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '4151b72b4e6f9a0e10fccb90e1be0e922566c30242e2a1a3bd5e74972c9ddd64'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Buen profe, explica bien y es muy entretenido durante las clases'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'bdd96c277c5037b4d71930a40c8a9aaaf1973c9c8a31159492cc176f652e678b'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'El profe es muy profesional, mientras que al mismo tiempo, logra brindar una sensación de respeto y compañerismo que es muy agradecida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-11-20T00:00:00+00:00'::TIMESTAMPTZ, '1d0f92ef3d29639e1dc126dbbf6749fce719e4850381d705ac9529cb8590bc2f'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'El mejor profe que se puede tener, muy amable, se ve que le interesa el aprendizaje de los estudiantes, 100% recomendado todos los profes de compu deberían ser así :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, '728c43fd41eb7a60af17c354421c8239bd5cfb892e328fdd3fa38e4468175a91'::TEXT, ARRAY[1039]::BIGINT[]),
    (315::BIGINT, 'Buen profe, las clases son entretenidas y se aprende bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-09-02T00:00:00+00:00'::TIMESTAMPTZ, '374edee693b39245d734b2c08f19a82a2edc9bea566ee45fae55dcb647924c5a'::TEXT, ARRAY[1039]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
